// Banco de preguntas tipo examen del módulo de seguridad (CCST Networking, dominio 6). Clave = nivel de práctica.
import { op, vs, rel, ord } from './_ayuda.mjs';

const REGLAS = ['Regla', 'Acción', 'Protocolo', 'Origen', 'Destino', 'Puerto destino'];

/* ================================================================ NIVEL 1 · Fundamentos */
const n1 = [
  op('Un técnico envía por error la lista de sueldos a toda la empresa. ¿Qué propiedad de la tríada CIA se vio afectada?', ['Disponibilidad', 'Integridad', 'Confidencialidad', 'No repudio'], 2, 'La información llegó a personas que no debían verla. Nadie la cambió (integridad) y sigue accesible (disponibilidad).'),
  op('Un atacante modifica el número de cuenta bancaria en una factura antes de que llegue al cliente. ¿Qué propiedad se rompe principalmente?', ['Integridad', 'Disponibilidad', 'Confidencialidad', 'Autorización'], 0, 'El dato fue alterado sin permiso: ya no es exacto. Aunque el atacante también lo haya leído, el daño que describe la pregunta es el cambio.'),
  op('El servidor de archivos se apaga por sobrecalentamiento porque falló el aire acondicionado del cuarto de equipos. ¿Qué propiedad se pierde?', ['Confidencialidad', 'Integridad', 'Autenticación', 'Disponibilidad'], 3, 'El servicio no está cuando se necesita. La disponibilidad también se pierde por causas ambientales, sin que haya atacante.'),
  op('¿Qué control protege principalmente la confidencialidad de los datos de una computadora portátil robada?', ['Un UPS', 'El cifrado del disco', 'Un segundo enlace a Internet', 'Un hash SHA-256 del disco'], 1, 'Sin la clave, el ladrón no puede leer el contenido. El UPS y el segundo enlace protegen la disponibilidad; el hash, la integridad.'),
  op('Una empresa guarda el hash de sus archivos de configuración y lo compara cada noche. ¿Qué busca proteger?', ['Disponibilidad', 'Confidencialidad', 'Integridad', 'Ancho de banda'], 2, 'Si el hash cambia, el archivo fue modificado. El hash no esconde el contenido ni mantiene el servicio activo.'),
  op('¿Cuál es la mejor definición de «vulnerabilidad»?', ['Una persona que quiere atacar la red', 'Una debilidad que una amenaza puede aprovechar', 'El programa que se usa para atacar', 'El dinero que se pierde en un incidente'], 1, 'La persona es una amenaza, el programa es un exploit y la pérdida es el impacto. La vulnerabilidad es el punto débil.'),
  op('Un servidor lleva tres años sin actualizaciones de seguridad. En términos de riesgo, eso es…', ['una amenaza', 'un exploit', 'una vulnerabilidad', 'una mitigación'], 2, 'La falta de parches es una debilidad del sistema. La amenaza sería quien la aproveche; la mitigación, instalar los parches.'),
  op('¿Qué es un exploit?', ['Una copia de seguridad', 'Una técnica o programa que aprovecha una vulnerabilidad concreta', 'Un tipo de firewall', 'Un usuario con muchos permisos'], 1, 'Es el instrumento que convierte una debilidad en un ataque real.'),
  op('Una empresa instala cámaras, firewall, antivirus, VLAN separadas y capacita a su personal. ¿Qué estrategia aplica?', ['Mínimo privilegio', 'Defensa en profundidad', 'Seguridad por oscuridad', 'Inicio de sesión único'], 1, 'Son varias capas distintas, de modo que el fallo de una no deja todo expuesto. Mínimo privilegio se refiere a los permisos de cada cuenta.'),
  op('La cuenta de un cajero puede consultar saldos pero no aprobar préstamos. ¿Qué principio se aplica?', ['Mínimo privilegio', 'Disponibilidad', 'Defensa en profundidad', 'Redundancia'], 0, 'Cada cuenta recibe solo los permisos que su función necesita.'),
  op('¿Por qué un técnico no debe trabajar todo el día con una cuenta de administrador?', ['Porque es más lenta', 'Porque cualquier malware que ejecute tendrá permisos totales', 'Porque caduca cada hora', 'Porque no puede abrir el navegador'], 1, 'El malware hereda los permisos de la cuenta que lo ejecuta. Con una cuenta normal, el daño queda limitado.'),
  op('Un visitante entra al cuarto de comunicaciones porque la puerta estaba abierta y conecta su portátil a un switch. ¿Qué tipo de control falló?', ['Lógico', 'Físico', 'Criptográfico', 'De respaldo'], 1, 'La puerta, la cerradura y el registro de visitas son controles físicos. Sin ellos, los controles lógicos se pueden saltar.'),
  op('¿Qué expresa mejor el concepto de riesgo?', ['La cantidad de equipos de una red', 'La probabilidad de que ocurra un incidente combinada con el daño que causaría', 'El número de contraseñas de un usuario', 'La velocidad de un ataque'], 1, 'Riesgo = probabilidad × impacto. Sirve para decidir qué proteger primero.'),
  op('Un incendio en el centro de datos es, en el vocabulario de seguridad…', ['una vulnerabilidad', 'un activo', 'una amenaza', 'un exploit'], 2, 'Es algo que podría causar daño. Las amenazas también pueden ser accidentes o desastres naturales.'),
  op('¿Cuál de estos es un activo de información?', ['Un correo de phishing', 'La base de datos de pacientes de una clínica', 'Un puerto abierto sin motivo', 'Un apagón'], 1, 'Un activo es lo valioso que se protege. El phishing y el apagón son amenazas; el puerto abierto, una vulnerabilidad.'),
  op('Una empresa cifra sus datos, pero no tiene copias de seguridad. Un disco se avería y se pierde todo. ¿Qué propiedad descuidó?', ['Confidencialidad', 'Disponibilidad', 'Autenticación', 'No repudio'], 1, 'El cifrado protegía la confidencialidad, pero sin respaldo los datos dejaron de estar disponibles.'),
  vs('¿Cuáles **dos** situaciones afectan a la **integridad**?', ['Un archivo se corrompe durante una transferencia', 'Un servidor se apaga por un corte de luz', 'Un empleado cambia sin permiso las calificaciones en un sistema escolar', 'Alguien lee un correo ajeno', 'El enlace a Internet se cae'], [0, 2], 'En ambas, los datos dejan de ser exactos. El apagón y la caída del enlace afectan la disponibilidad; leer un correo ajeno, la confidencialidad.'),
  vs('¿Cuáles **dos** controles protegen principalmente la **confidencialidad**?', ['Cifrado del tráfico con una VPN', 'Discos en espejo', 'Permisos de acceso a carpetas', 'Generador eléctrico', 'Hash de archivos'], [0, 2], 'Cifrar y restringir quién puede leer evitan que la información llegue a quien no debe. Los discos en espejo y el generador son de disponibilidad; el hash, de integridad.'),
  vs('¿Cuáles **dos** son ejemplos de **mitigación**?', ['Instalar los parches de seguridad', 'Un grupo de delincuentes', 'Una contraseña de fábrica', 'Activar la autenticación multifactor', 'Una inundación'], [0, 3], 'Parchear y activar MFA reducen el riesgo. Los delincuentes y la inundación son amenazas; la contraseña de fábrica, una vulnerabilidad.'),
  vs('¿Cuáles **dos** medidas son de **seguridad física**?', ['Cerradura en el rack de comunicaciones', 'Firewall con estado', 'Registro de visitas al centro de datos', 'Cifrado AES', 'Contraseñas largas'], [0, 2], 'La cerradura y el registro de visitas controlan quién toca los equipos. Las demás son controles lógicos.'),
  vs('¿Cuáles **dos** son amenazas (y no vulnerabilidades)?', ['Un empleado descontento con acceso a los sistemas', 'Un router con la contraseña de fábrica', 'Una campaña de ransomware en circulación', 'Un servidor sin parches', 'Una puerta que no cierra'], [0, 2], 'El empleado y la campaña pueden causar daño: son amenazas. Las otras tres son debilidades que una amenaza podría aprovechar.'),
  rel('Relaciona cada situación con la propiedad de la tríada CIA afectada.', [['Un desconocido lee el tráfico de una Wi-Fi abierta', 'Confidencialidad'], ['Un ataque deja fuera de línea la tienda web', 'Disponibilidad'], ['Alguien cambia el contenido de un contrato firmado', 'Integridad'], ['Se pierde un teléfono sin bloqueo con correos de la empresa', 'Confidencialidad']], 'Leer o exponer = confidencialidad; dejar sin servicio = disponibilidad; cambiar = integridad.'),
  rel('Relaciona cada término con su ejemplo.', [['Activo', 'El servidor de facturación'], ['Amenaza', 'Un delincuente que busca robar datos'], ['Vulnerabilidad', 'Un sistema operativo sin actualizar'], ['Mitigación', 'Instalar las actualizaciones pendientes']], 'El activo es lo que se protege, la amenaza lo que puede dañarlo, la vulnerabilidad la debilidad y la mitigación la medida que reduce el riesgo.', ['Un cable de categoría 6']),
  ord('Ordena las capas de la defensa en profundidad, de la más externa a la más cercana a los datos.', ['Seguridad física del edificio', 'Firewall en el perímetro de la red', 'Antivirus y firewall en cada equipo', 'Permisos y cifrado de los datos'], 'Se va de fuera hacia dentro: edificio, frontera de la red, equipo y, por último, los propios datos.'),
];

/* ================================================================ NIVEL 2 · Amenazas */
const n2 = [
  op('Un usuario recibe un correo que aparenta ser de su banco y le pide «verificar su cuenta» en un enlace. ¿Qué tipo de ataque es?', ['Ransomware', 'Phishing', 'Denegación de servicio', 'Fuerza bruta'], 1, 'Suplanta a una entidad de confianza por correo para robar credenciales. No cifra archivos ni satura servicios.'),
  op('La gerente de finanzas recibe un correo con su nombre, su puesto y el nombre real de un proveedor, que le pide cambiar la cuenta de pago. ¿Qué variante de phishing es?', ['Smishing', 'Vishing', 'Spear phishing', 'Spam'], 2, 'Está personalizado para una persona concreta con datos reales. Smishing y vishing se definen por el canal (SMS y voz); el spam es publicidad masiva.'),
  op('Alguien llama a un empleado diciendo ser del banco y le pide el código que acaba de recibir por SMS. ¿Cómo se llama esta técnica?', ['Vishing', 'Whaling', 'Adware', 'Gusano'], 0, 'El engaño llega por una llamada de voz. Además, intenta saltarse el segundo factor: ese código nunca se comparte.'),
  op('Un malware cifra los documentos de un equipo y exige un pago para devolverlos. ¿Qué es?', ['Spyware', 'Ransomware', 'Rootkit', 'Adware'], 1, 'El cifrado de archivos con petición de rescate es la marca del ransomware.'),
  op('¿Cuál es la mejor defensa para recuperarse de un ransomware sin pagar?', ['Un firewall de nueva generación', 'Copias de seguridad recientes, probadas y aisladas de la red', 'Una contraseña de Wi-Fi más larga', 'Ocultar el SSID'], 1, 'Solo una copia que el malware no haya alcanzado permite restaurar. Las demás medidas ayudan a prevenir, no a recuperar.'),
  op('Un programa malicioso se extiende por toda la red en minutos aprovechando un fallo del sistema, sin que ningún usuario abra nada. ¿Qué tipo de malware es?', ['Virus', 'Troyano', 'Gusano', 'Adware'], 2, 'La propagación automática por la red define al gusano. El virus necesita que alguien ejecute un archivo y el troyano, que alguien lo instale.'),
  op('Un usuario instala un «optimizador de PC» gratuito que, además de lo prometido, da acceso remoto a un atacante. ¿Qué es?', ['Troyano', 'Gusano', 'Botnet', 'Spam'], 0, 'Se presenta como software útil para que la víctima lo instale por su cuenta.'),
  op('¿Qué tipo de malware registra las pulsaciones del teclado para robar contraseñas?', ['Adware', 'Spyware (registrador de teclas)', 'Ransomware', 'Gusano'], 1, 'Un registrador de teclas es spyware: espía al usuario y envía lo capturado a un tercero.'),
  op('Un sitio web recibe tráfico masivo desde decenas de miles de dispositivos infectados de todo el mundo y deja de responder. ¿Qué ataque es?', ['DoS', 'DDoS', 'Intermediario', 'Diccionario'], 1, 'Muchos orígenes a la vez = distribuido. Un DoS simple vendría de un solo origen.'),
  op('¿Cómo se llama el conjunto de equipos infectados que un atacante controla a distancia para lanzar ataques?', ['Botnet', 'DMZ', 'VLAN', 'Rootkit'], 0, 'Una botnet es una red de «zombis». Es la herramienta habitual detrás de un DDoS.'),
  op('En una cafetería, un atacante crea un punto de acceso con el mismo nombre que la red oficial y captura el tráfico de quienes se conectan. ¿Qué ataque es?', ['Fuerza bruta', 'Intermediario (on-path)', 'Ransomware', 'Smishing'], 1, 'El atacante se coloca entre la víctima e Internet. Se le conoce también como punto de acceso gemelo.'),
  op('Los registros muestran miles de intentos de inicio de sesión contra una cuenta, usando contraseñas de una lista de las más comunes. ¿Qué ataque es?', ['De diccionario', 'DDoS', 'Phishing', 'Reconocimiento'], 0, 'Usa una lista de contraseñas probables en vez de probar todas las combinaciones (eso sería fuerza bruta).'),
  op('Una persona sin gafete entra a la oficina caminando justo detrás de un empleado que abrió la puerta con su tarjeta. ¿Qué técnica usó?', ['Vishing', 'Tailgating', 'Baiting', 'Whaling'], 1, 'Colarse detrás de alguien autorizado es tailgating, una forma de ingeniería social presencial.'),
  op('Un usuario avisa que hizo clic en un enlace sospechoso y escribió su contraseña. ¿Qué debe hacerse primero?', ['Esperar a ver si ocurre algo raro', 'Cambiar esa contraseña de inmediato y reportar el incidente', 'Borrar el correo y no decir nada', 'Reinstalar el navegador'], 1, 'La contraseña ya está comprometida: hay que cambiarla cuanto antes y avisar para que se revise la cuenta.'),
  op('Un equipo de la oficina muestra señales claras de malware. ¿Cuál es la primera acción técnica recomendada?', ['Desconectarlo de la red', 'Formatearlo sin avisar', 'Seguir usándolo con cuidado', 'Conectarle una memoria USB para copiar los archivos'], 0, 'Aislarlo evita la propagación. Formatear destruye evidencia y la memoria USB podría infectarse.'),
  op('El firewall registra que una misma IP externa probó en secuencia cientos de puertos de un servidor. ¿En qué fase de un ataque se encuentra probablemente?', ['Reconocimiento', 'Cifrado de archivos', 'Petición de rescate', 'Recuperación'], 0, 'El escaneo de puertos sirve para descubrir qué servicios hay. Es información previa al ataque.'),
  vs('¿Cuáles **dos** tipos de malware se caracterizan por **cómo se propagan**?', ['Virus', 'Ransomware', 'Gusano', 'Spyware', 'Adware'], [0, 2], 'El virus se propaga adjunto a archivos que alguien abre y el gusano, solo por la red. Los otros tres se definen por lo que hacen.'),
  vs('¿Cuáles **dos** ataques son de **ingeniería social**?', ['Phishing', 'DDoS', 'Suplantación de un técnico por teléfono', 'Fuerza bruta', 'Escaneo de puertos'], [0, 2], 'Ambos engañan a una persona. Los otros atacan servicios o contraseñas sin manipular a nadie.'),
  vs('¿Cuáles **dos** acciones debe evitar un técnico ante un equipo con ransomware?', ['Pagar el rescate por su cuenta', 'Desconectar el equipo de la red', 'Reportar el incidente', 'Formatear el equipo antes de avisar', 'Documentar lo observado'], [0, 3], 'Pagar no garantiza nada y financia al atacante; formatear destruye evidencia. Las otras tres son justo lo que hay que hacer.'),
  vs('¿Cuáles **dos** señales hacen sospechar de un correo?', ['El enlace visible dice una dirección y al pasar el cursor aparece otra', 'Está firmado por el remitente', 'Exige actuar en menos de una hora', 'Viene de un compañero con el que hablas a diario sobre el mismo tema', 'No lleva adjuntos'], [0, 2], 'Un enlace que no coincide y la presión de tiempo son señales clásicas de phishing.'),
  vs('¿Cuáles **dos** medidas reducen el riesgo de un ataque de intermediario?', ['Usar HTTPS', 'Conectarse a cualquier Wi-Fi abierta', 'Usar una VPN', 'Ignorar los avisos de certificado', 'Desactivar las actualizaciones'], [0, 2], 'El cifrado de extremo a extremo impide leer o alterar el tráfico. Ignorar avisos de certificado es justo lo que el atacante necesita.'),
  rel('Relaciona cada malware con lo que lo caracteriza.', [['Ransomware', 'Cifra archivos y pide un pago'], ['Gusano', 'Se propaga solo por la red'], ['Troyano', 'Se disfraza de programa legítimo'], ['Spyware', 'Espía la actividad del usuario']], 'Rescate, propagación automática, disfraz y espionaje: la palabra clave de cada uno.', ['Muestra publicidad no deseada']),
  rel('Relaciona cada técnica de ingeniería social con su canal o método.', [['Phishing', 'Correo electrónico masivo'], ['Smishing', 'Mensaje de texto'], ['Vishing', 'Llamada telefónica'], ['Baiting', 'Memoria USB abandonada']], 'Phishing por correo, smishing por SMS, vishing por voz y baiting con un cebo físico.'),
  ord('Ordena la respuesta de un técnico ante un equipo infectado.', ['Aislar el equipo de la red', 'Reportar al equipo de seguridad', 'Documentar lo ocurrido en el ticket', 'Restaurar desde una copia de seguridad cuando lo autoricen'], 'Contener, escalar, documentar y recuperar, en ese orden.'),
];

